template <typename T>
class Matrix {
    public:
        Matrix() = default;
        Matrix(std::size_t rows, std::size_t columns, const T& value)
            : m_(rows), n_(columns), data_(rows * columns, value) {}

        T& operator()(std::size_t i, std::size_t j) {
            assert(i < m_ && j < n_);
            return data_[i * n_ + j];
        }
        const T& operator()(std::size_t i, std::size_t j) const {
            assert(i < m_ && j < n_);
            return data_[i * n_ + j];
        }

        std::size_t rows()    const { return m_; }
        std::size_t columns() const { return n_; }

        auto begin()       { return data_.begin(); }
        auto end()         { return data_.end(); }
        auto begin() const { return data_.begin(); }
        auto end()   const { return data_.end(); }

    private:
        std::size_t m_ = 0, n_ = 0;
        std::vector<T> data_;
};

struct KST;

struct Edge {
    bool active = true;
    std::vector<KST*> KSTs;

    void addKST(KST* kst);
    void removeKST(KST* kst);
};

struct KST {
    int id = 0;
    bool alive = true;
    std::vector<Edge*> edges;
    int soloEdges = 0;

    void incSoloEdges() { soloEdges++; }
    void decSoloEdges() { soloEdges--; }
};

struct position {
    int row;
    int column;
};

